using Npgsql;using SanSo.Api.Modules;using SanSo.Api.V2;
namespace SanSo.Api.V5;
public sealed class PostgresInventoryStoreV4(NpgsqlDataSource dataSource)
{
 public async Task<InventoryBalance> Get(string tenant,string sku,CancellationToken ct){await using var c=await Open(tenant,ct);return await Read(c,tenant,sku,ct);}
 public async Task<InventoryBalance> Reserve(string tenant,string sku,int quantity,string sourceKey,CancellationToken ct){if(quantity<=0)throw new ArgumentOutOfRangeException(nameof(quantity));await using var c=await Open(tenant,ct);await using var tx=await c.BeginTransactionAsync(System.Data.IsolationLevel.ReadCommitted,ct);if(await Exists(c,tx,tenant,sourceKey,ct)){await tx.CommitAsync(ct);return await Read(c,tenant,sku,ct);}var row=await Lock(c,tx,tenant,sku,ct);if(row.OnHand-row.Reserved-row.Quarantine<quantity)throw new InventoryConflictException();await Change(c,tx,tenant,row.Product,row.Location,quantity,"reserved=reserved+$1",ct);await Movement(c,tx,tenant,row.Product,row.Location,"RESERVE",quantity,sourceKey,ct);await tx.CommitAsync(ct);return new(tenant,sku,row.OnHand,row.Reserved+quantity,row.Quarantine,row.Version+1);}
 public async Task<InventoryBalance> Release(string tenant,string sku,int quantity,string sourceKey,CancellationToken ct){if(quantity<=0)throw new ArgumentOutOfRangeException(nameof(quantity));await using var c=await Open(tenant,ct);await using var tx=await c.BeginTransactionAsync(System.Data.IsolationLevel.ReadCommitted,ct);if(await Exists(c,tx,tenant,sourceKey,ct)){await tx.CommitAsync(ct);return await Read(c,tenant,sku,ct);}var row=await Lock(c,tx,tenant,sku,ct);if(row.Reserved<quantity)throw new InvalidOperationException("CANNOT_RELEASE_MORE_THAN_RESERVED");await Change(c,tx,tenant,row.Product,row.Location,quantity,"reserved=reserved-$1",ct);await Movement(c,tx,tenant,row.Product,row.Location,"RELEASE",quantity,sourceKey,ct);await tx.CommitAsync(ct);return new(tenant,sku,row.OnHand,row.Reserved-quantity,row.Quarantine,row.Version+1);}
 static async Task<bool> Exists(NpgsqlConnection c,NpgsqlTransaction tx,string tenant,string key,CancellationToken ct){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT 1 FROM inventory_movements WHERE organization_id=$1::uuid AND source_key=$2";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(key);return await q.ExecuteScalarAsync(ct)is not null;}static async Task<(Guid Product,Guid Location,int OnHand,int Reserved,int Quarantine,long Version)> Lock(NpgsqlConnection c,NpgsqlTransaction tx,string tenant,string sku,CancellationToken ct){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT p.id,l.id,b.on_hand,b.reserved,b.quarantine,b.version FROM inventory_balances b JOIN products p ON p.id=b.product_id JOIN inventory_locations l ON l.id=b.location_id WHERE b.organization_id=$1::uuid AND p.canonical_sku=$2 FOR UPDATE";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(sku);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new KeyNotFoundException("Inventory balance not found");return(r.GetGuid(0),r.GetGuid(1),r.GetInt32(2),r.GetInt32(3),r.GetInt32(4),r.GetInt64(5));}static async Task Change(NpgsqlConnection c,NpgsqlTransaction tx,string tenant,Guid product,Guid location,int quantity,string expression,CancellationToken ct){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=$"UPDATE inventory_balances SET {expression},version=version+1 WHERE organization_id=$2::uuid AND product_id=$3 AND location_id=$4";q.Parameters.AddWithValue(quantity);q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(product);q.Parameters.AddWithValue(location);if(await q.ExecuteNonQueryAsync(ct)!=1)throw new InvalidOperationException("INVENTORY_BALANCE_UPDATE_LOST");}static async Task Movement(NpgsqlConnection c,NpgsqlTransaction tx,string tenant,Guid product,Guid location,string type,int quantity,string key,CancellationToken ct){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT INTO inventory_movements(organization_id,product_id,location_id,type,quantity,source_key,occurred_at) VALUES($1::uuid,$2,$3,$4,$5,$6,now())";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(product);q.Parameters.AddWithValue(location);q.Parameters.AddWithValue(type);q.Parameters.AddWithValue(quantity);q.Parameters.AddWithValue(key);await q.ExecuteNonQueryAsync(ct);}static async Task<InventoryBalance> Read(NpgsqlConnection c,string tenant,string sku,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText="SELECT b.on_hand,b.reserved,b.quarantine,b.version FROM inventory_balances b JOIN products p ON p.id=b.product_id WHERE b.organization_id=$1::uuid AND p.canonical_sku=$2";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(sku);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new KeyNotFoundException("Inventory balance not found");return new(tenant,sku,r.GetInt32(0),r.GetInt32(1),r.GetInt32(2),r.GetInt64(3));}async Task<NpgsqlConnection> Open(string tenant,CancellationToken ct){var c=await dataSource.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT set_config('app.current_organization_id',$1,false)";q.Parameters.AddWithValue(tenant);await q.ExecuteNonQueryAsync(ct);return c;}
}
